/**
 * Lightweight Markdown Parser for English Master AI
 */
(function (global) {
  function escapeHtml(text) {
    return text
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function parse(markdown) {
    if (!markdown) return "";
    let html = markdown;

    // Normalize newlines
    html = html.replace(/\r\n/g, "\n");

    // Code blocks with syntax tag
    html = html.replace(/```([a-zA-Z0-9_\-\+\#]*)\n([\s\S]*?)```/g, function (match, lang, code) {
      return `<pre class="ema-code-block"><div class="ema-code-lang">${escapeHtml(lang || "text")}</div><code>${escapeHtml(code.trim())}</code></pre>`;
    });

    // Inline code
    html = html.replace(/`([^`]+)`/g, function (match, code) {
      return `<code class="ema-inline-code">${escapeHtml(code)}</code>`;
    });

    // Headers
    html = html.replace(/^### (.*$)/gim, '<h4 class="ema-h4">$1</h4>');
    html = html.replace(/^## (.*$)/gim, '<h3 class="ema-h3">$1</h3>');
    html = html.replace(/^# (.*$)/gim, '<h2 class="ema-h2">$1</h2>');

    // Blockquotes & Callouts
    html = html.replace(/^\> (.*$)/gim, '<blockquote class="ema-quote">$1</blockquote>');

    // Bold & Italic
    html = html.replace(/\*\*\*([^*]+)\*\*\*/g, '<strong><em>$1</em></strong>');
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong class="ema-strong">$1</strong>');
    html = html.replace(/\*([^*]+)\*/g, '<em class="ema-em">$1</em>');

    // Key Highlights (e.g. [A], [B], [C], [D] or Correct Answer tags)
    html = html.replace(/\[([A-D])\]/g, '<span class="ema-choice-tag">[$1]</span>');
    html = html.replace(/(✅|ĐÁP ÁN ĐÚNG|CORRECT ANSWER:?)/gi, '<span class="ema-badge-success">$1</span>');

    // Unordered lists
    html = html.replace(/^\s*[\-\*]\s+(.*)$/gim, '<li class="ema-li">$1</li>');
    html = html.replace(/(<li class="ema-li">.*<\/li>(\n)?)+/g, '<ul class="ema-ul">$&</ul>');

    // Ordered lists
    html = html.replace(/^\s*(\d+)\.\s+(.*)$/gim, '<li class="ema-li-num">$2</li>');
    html = html.replace(/(<li class="ema-li-num">.*<\/li>(\n)?)+/g, '<ol class="ema-ol">$&</ol>');

    // Paragraphs
    let paragraphs = html.split(/\n\n+/);
    html = paragraphs.map(p => {
      p = p.trim();
      if (!p) return "";
      if (p.startsWith("<h") || p.startsWith("<pre") || p.startsWith("<ul") || p.startsWith("<ol") || p.startsWith("<blockquote")) {
        return p;
      }
      return `<p class="ema-p">${p.replace(/\n/g, "<br/>")}</p>`;
    }).filter(Boolean).join("\n");

    return html;
  }

  const marked = {
    parse: parse
  };

  if (typeof module !== "undefined" && module.exports) {
    module.exports = marked;
  } else {
    global.marked = marked;
  }
})(typeof window !== "undefined" ? window : this);
